    seen = set()
    counts = Counter()

    def bfs(color, start):
        """Do BFS to find all connected cells of same color"""
        queue = deque([start])
        component = [start]
        seen.add(start)
        colors_set = {color}
        while queue:
            r, c = queue.popleft()
            for dr, dc in [(-1,0), (1,0), (0,-1), (0,1)]:
                nr, nc = r + dr, c + dc
                if 0 <= nr < len(grid) and 0 <= nc < len(grid[0]):
                    if grid[nr][nc] == color and (nr, nc) not in seen:
                        seen.add((nr, nc))
                        queue.append((nr, nc))
                        component.append((nr, nc))
